-- GENERATED by `wfj generate` from data/gossip/gossip-1a.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["1a1a96cd7a7419b5"] = { "Ehi! Allontanati da lì!", "." },
  ["1a1ec46941144445"] = { "Vuoi abbassare le nostre difese globali per accontentare un magistrato paranoico e un accampamento di gentaglia che con ogni probabilità soffre di un colpo di calore.", "." },
  ["1a29e24c7eed9805"] = { "Ti ha convocato Lago Blackwrench, maestro degli stregoni di ⟦Ironforge=Forgiardente⟧. Faresti bene a presentarti da lui subito. Lo troverai nel quartiere della Forlorn Cavern.", "." },
  ["1a31df40b39600f0"] = { "Che altro hai da dire?", "." },
  ["1a3b9cb1a8bb7ea2"] = { "Porterò le tue viscere come collana.", "." },
  ["1a42443c103d7dff"] = { "Malton, zuccone!", "." },
  ["1a47508355eb9d1d"] = { "Aiuto! Toglietemi di dosso {name}!", "." },
  ["1a47573fc0445b05"] = { "Dove posso migliorare la mia abilità nello scasso?", "." },
  ["1a48b6bc052e484c"] = { "Sono pezzi pregiati, {name}. Lascia che inizi a lavorare alla tua tonaca.", "." },
  ["1a4a77d9dc78b302"] = { "Arriva la fiera!", "." },
  ["1a4b4185a2790497"] = { "È storia... Una storia di ⟦Silithus=Silitus⟧... di ⟦Ahn'Qiraj=Ahn'qiraj⟧... di Titani e di Dei Antichi... Leggo dalla profezia di C'Thun scritta dal profeta qiraji Skerram. Una profezia che preannuncia un cataclisma...", "." },
  ["1a5793fcfaed5bc8"] = { "Salute, {race}. Una giornata meravigliosa per essere vivi, non trovi?", "." },
  ["1a5acff9ff91643f"] = { "I Kolkar sono i più forti!", "." },
  ["1a60ae6d9072011c"] = { "Non rovinerai le mie terre, feccia!", "." },
  ["1a62145b911c04e7"] = { "Quanti rifornimenti servono ancora per lanciare un assalto via terra?", "." },
  ["1a6782030c362b3d"] = { "Il Signet of Chaos appartiene a ⟦Ravenholdt=Corvolesto⟧, bestia! Non avrai mai il suo potere! (PLACEHOLDER - DA SPOSTARE/MODIFICARE)", "." },
  ["1a67f7598c9ffdd5"] = { "{name} conquista le stalle! Senza un contrattacco, l'⟦Alliance=Alleanza⟧ le controllerà tra 1 minuto!", "." },
  ["1a6bcbca8d1be1bc"] = { "Com'è potuto succedere, {name}? Credi che un oggetto come lo ⟦Scepter of Celebras=Scettro di Celebras⟧ sia una cosa da poco?\n\nQuesta volta posso aiutarti, ma non essere di nuovo così <incauto/incauta> con questo prezioso oggetto...", "." },
  ["1a6dfc1545b4ca97"] = { "Inserimento della scheda di sicurezza bianca riuscito...\n\nErogazione dell'unità di livello di sicurezza beta.\n\n01010000 01101100 01100001 01111001 00100000 01110100 01101000 01100101 00100000 01010111 01100001 01110010 01100011 01100001 01110010 01100110 01110100 00100000 01110010 01101111 01101100 01100101 01110000 01101100 01100001 01111001 01101001 01101110 01100111 00100000 01100111 01100001 01101101 01100101", "." },
  ["1a7448a2e43a4dd6"] = { "<Cattivo/Cattiva>, {name}. {name}, <cattivo/cattiva>!", "." },
  ["1a78efb7a62fe1e5"] = { "Non sei molto <sveglio/sveglia>, eh? Mmh, se facessi lo stalliere, magari starei nei paraggi di, che so, la stalla? Cerca Morganus laggiù.", "." },
  ["1a7c956a1520d7e6"] = { "Lo ⟦The Scepter of the Shifting Sands=Scettro delle Sabbie Mutevoli⟧ è di nuovo intero, {name}.\n\nDevi essere tu a usare lo scettro. Devi essere tu ad annunciare la nuova era del tuo popolo.\n\nQuando sarai <pronto/pronta> a suonare lo Scarab Gong e ad aprire di nuovo i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧, ti consegnerò lo Scettro. Devi solo chiedere.", "." },
  ["1a7e6dde1219b912"] = { "Ti prego, ti prego, ti prego, dimmi che sei qui per liberarmi da queste catene. Dev'esserci una chiave da qualche parte...\n\nO almeno, magari puoi far fuori la guardia Slip'kik. Credo di poterti dare una mano!\n\nVedi quella trappola rotta laggiù? Gli ogre sono troppo stupidi per capire come aggiustarla. Si vede che le servono un Meccanismo di Torio e un po' di Olio del Freddo. Se la ripari, scommetto che potresti attirarci dentro Slip'kik e BLAMMO: guardia ogre in trappola!", "." },
  ["1a7ea056c0e906af"] = { "Ho perso il mio ⟦Dagger of Veiled Shadows=Pugnale delle Ombre Velate⟧. Puoi sostituirmelo?", "." },
  ["1a891350f5b58355"] = { "L'anziano Nightwind passa i giorni al santuario di Jaedenar, a ⟦Felwood=Vilbosco⟧.", "." },
  ["1a8df22b29a4bca9"] = { "Voglio vedere la tua merce.", "." },
  ["1a99ae9126e85bee"] = { "Se ti serve addestramento in alchimia, c'è un solo posto a ⟦Stormwind=Roccavento⟧ dove devi andare... Alchemy Needs. Lo trovi nel ⟦Mage Quarter=Quartiere dei Maghi⟧, lungo il giro esterno di negozi.", "." },
  ["1a9e268832814f23"] = { "Va bene, va bene! Non c'è bisogno di diventare violenti. Parlo. Parlo!", "." },
  ["1a9f490858fc048c"] = { "E vorrei poter venire con te, {name}. Vai al Castello di ⟦Stormwind=Roccavento⟧. Troverai Thelman Slatefist nella sala delle udienze del re. Ti aiuterà a raggiungere la ⟦Alterac Valley=Valle d'Alterac⟧.", "." },
  ["1aad6cc39f78c3e6"] = { "Mmh, stavolta queste ossa sono niente male, Pozzik.", "." },
  ["1ab6364479e5e585"] = { "Perché mi hai evocato così presto? Non ho ancora raggiunto la mia piena potenza!", "." },
  ["1ac02d0deabb9a5c"] = { "Falthir, ho bisogno di aiuto per recuperare un pezzo del mio completo degli Scriteriati.", "." },
  ["1ac0abc871f5b9ad"] = { "Se riuscissi a pescare un pesce grande quanto la tua bocca, non avremmo mai più fame.", "." },
  ["1ac14b301de111a1"] = { "Un arco è una gran cosa, amico mio. Tu devi solo trattarlo bene, e lui tratta bene te.", "." },
  ["1ac3cb82ed0f3fa5"] = { "Oggetti antichi, armi da guerra, armature rare. Chissà cosa porterà Antonio questa settimana, se non vieni a dare un'occhiata.", "." },
  ["1ac4da0437169428"] = { "Questo raggio di luna ti porterà a Orgrimmar. Usa il tuo invito quando vuoi partire.", "." },
  ["1ad33873d7be38d8"] = { "Brzzzzt!\n\n<Benvenuto/Benvenuta> al Matrix Punchograph 3005 barra D, un terminale di livello di sicurezza delta.\n\nRilevata scheda perforata rossa. Accesso consentito.\n\n01001000 01101111 01110111 00100000 01100001 01101101 00100000 01001001 00100000 01100100 01110010 01101001 01110110 01101001 01101110 01100111 00111111", "." },
  ["1adb7b39c6dcd269"] = { "Che Cenarius ti guidi, {class}.\n\nSono in questa terra corrotta con le mie sorelle per una missione di grande importanza per il Circolo Cenariano. Ma chiedo che a parlarmi di tali questioni siano solo coloro che hanno abbastanza potere: mandare un essere inferiore sarebbe una follia.", "." },
  ["1adc51f31f493cac"] = { "Sì, ho controllato, mi manca il pezzo di sopra!", "." },
  ["1adc9d123e75df6c"] = { "Ehi, <ragazzo/ragazza>, sei <pronto/pronta> ad andare nella ⟦Alterac Valley=Valle d'Alterac⟧ e dare all'⟦Horde=Orda⟧ un assaggio di quello che vanno cercando?", "." },
  ["1ae2e6c528605f7a"] = { "Va bene... quindi vuoi fare <il/la> <sarto/sarta>. Che ne dici di dimostrarlo?", "." },
  ["1ae4ec0693b22569"] = { "Ce l'ho fatta! Ho imbrigliato il potere della pietra negli occhiali! Andiamocene da qui!", "." },
  ["1ae589c70bbcd74d"] = { "Per quanto letali sembrino i silitidi, non sono che creature mansuete in confronto ai loro signori Qiraji.", "." },
  ["1ae5c49ce78d0967"] = { "Come se alla mia età non avessi niente di meglio da fare che portare secchi d'acqua.", "." },
  ["1ae75e1555e915af"] = { "Noi Mordilegno possiamo garantirti un passaggio sicuro attraverso il rifugio, ma devi dimostrarti <degno/degna> del nostro aiuto.", "." },
  ["1ae8aa44dacfd56e"] = { "È per me un grande piacere incontrare finalmente qualcuno del tuo popolo. Ho sentito molto parlare degli shen'dorei e della vostra lunga storia, e mi rallegra vedere i nostri cugini tornare finalmente a casa, a Kalimdor.\r\n\nConfesso che il nostro popolo ha un rapporto... complicato con gli ⟦Highborne=Alti Nobili⟧. Alcuni elfi della notte sono pronti a diffidare di chi discende dagli ⟦Highborne=Alti Nobili⟧, come i membri del vostro High Order. Tuttavia, hai la mia assicurazione che sarai <trattato/trattata> con il massimo rispetto mentre sei ospite nella nostra città.\r\n\nTi prego, fai come se fossi a casa tua. Ti incoraggio a esplorare e a familiarizzare con la nostra cultura. Dopotutto, in un certo senso è anche la tua cultura.", "." },
  ["1af5512a0dc5e536"] = { "Il ⟦Snowfall Graveyard=Cimitero di Nevealta⟧ è stato conquistato dall'⟦Horde=Orda⟧!", "." },
  ["1af56a9bc4b895aa"] = { "Nessun sopravvissuto!", "." },
})
